const SKILL_TREE_UF_BOUNDS_10H = {
  'changedling|damageTakenMult': { min:-0.25, max:0.6 },
  'changedling|radius':          { min:-2,    max:2 },
  'changelingqueen|damageTakenMult': { min:-0.25, max:0.6 },
  'changelingqueen|radius':          { min:-2,    max:2 },
  'filly|damageTakenMult': { min:-0.25, max:0.6 },
  'filly|radius':          { min:-2,    max:2 },
};

function ST10H(classId, stat, amount, perRank){
  const e = { type:'stat', classId, stat, amount };
  if (perRank != null) e.perRank = perRank;
  return e;
}
function UF10H(classId, field, amount){
  const b = SKILL_TREE_UF_BOUNDS_10H[classId + '|' + field];
  return { type:'uniqueField', classId, field, amount, min:b.min, max:b.max };
}
function FL10H(classId, field, value){ return { type:'uniqueFlag', classId, field, value }; }
function SY10H(classId, stat, perOwned, tag){ return { type:'synergyStat', classId, stat, perOwned, tag }; }

